SELECT public.fn_cron_safe_run(166::bigint, $sql$
  UPDATE products SET is_active = false, updated_at = now()
  WHERE is_active = true AND supplier_reference IS NULL AND sku IS NULL AND supplier_id IS NOT NULL;
  UPDATE products SET is_active = false, updated_at = now()
  WHERE 'active' = ANY(COALESCE(locked_fields, '{}')) AND is_active = true;
  UPDATE products SET is_active = true, updated_at = now()
  WHERE sku LIKE 'XBZ-MANUAL-%' AND is_active = false AND is_deleted = false;
$sql$, 44000, 'fantasmas-guard');

SELECT public.fn_cron_safe_run(149::bigint, $sql$
    UPDATE public.ai_usage_logs SET status='error', error_message='orphaned_pending: isolate killed before updateAiLog ran'
    WHERE status='pending' AND created_at < NOW() - INTERVAL '5 minutes';
  $sql$, 15000, 'ai-log-cleanup');

SELECT public.fn_cron_safe_run(38::bigint, $sql$
    DELETE FROM user_token_revocations
    WHERE (expires_at IS NOT NULL AND expires_at < now() - interval '5 minutes')
       OR (expires_at IS NULL AND revoked_at < now() - interval '30 days');
  $sql$, 30000, 'cleanup-token-revoc');

SELECT public.fn_cron_safe_run(154::bigint, $sql$
    UPDATE ai_enrichment_queue SET status='pending', locked_by=NULL, locked_at=NULL,
        last_error='cron-reset:stuck>'||ROUND(EXTRACT(EPOCH FROM (now()-locked_at))/3600,1)||'h', updated_at=now()
    WHERE status='processing' AND locked_at < now() - interval '2 hours' AND attempts < max_attempts;
    UPDATE ai_enrichment_queue SET status='error', locked_by=NULL, locked_at=NULL,
        last_error=COALESCE(last_error,'')||' | exhausted-max='||attempts::text, updated_at=now()
    WHERE status='processing' AND locked_at < now() - interval '1 hour' AND attempts >= max_attempts;
    UPDATE ai_enrichment_queue SET status='error',
        last_error=COALESCE(last_error,'')||' | pending-exhausted-max='||attempts::text, updated_at=now()
    WHERE status='pending' AND attempts >= max_attempts;
    UPDATE ai_enrichment_queue SET locked_by=NULL, locked_at=NULL, updated_at=now()
    WHERE status NOT IN ('processing','pending') AND locked_by IS NOT NULL;
  $sql$, 30000, 'ai-queue-stuck');

SELECT public.fn_cron_safe_run(136::bigint, $sql$
    UPDATE image_backfill_queue SET created_at = NOW()
    WHERE status = 'pending' AND created_at <= NOW() - INTERVAL '22 hours';
  $sql$, 30000, 'backfill-queue-expiry');

SELECT public.fn_cron_safe_run(50::bigint,
    'DELETE FROM public.cron_job_run_details_archive WHERE end_time < now() - interval ''90 days'';',
    44000, 'cleanup-log-weekly');

functions.comment:
Extrai informações de embalagem da descrição do produto.
Procura padrões como "Fornecido em caixa presente", "Inclui estojo", etc.
Retorna: {found, packaging_type (box/pouch/bag), packaging_text, is_gift_packaging, source}

Recalcula sale_price usando a hierarquia de markup_configurations.
Útil após alterar markup via fn_set_markup.
Exemplos:
  SELECT fn_recalcular_markup('supplier', 'uuid-xbz');
  SELECT fn_recalcular_markup('category', 'uuid-cat');
  SELECT fn_recalcular_markup('product',  'uuid-prod');
  SELECT fn_recalcular_markup('all');

Re-sincroniza manualmente os campos de imagem em products a partir de product_images.
   Útil quando o trigger falhou ou produto recebeu imagens sem disparar sync.

   Uso:
     -- Resync de produtos específicos:
     SELECT * FROM fn_resync_product_image_urls(ARRAY['uuid1', 'uuid2']::UUID[]);

     -- Resync de TODOS (só onde URL mudou):
     SELECT * FROM fn_resync_product_image_urls();

     -- Forçar resync de todos mesmo sem mudança:
     SELECT * FROM fn_resync_product_image_urls(NULL, TRUE);

   Adicionada 2026-06-15.

Configura a quantidade mínima de uma categoria pelo slug.
Exemplo: SELECT * FROM fn_set_category_min_quantity('canetas', 50);
Retorna: categoria atualizada e quantidade de produtos afetados.

Configura markup (%) por nível: supplier | category | product.
Cria nova regra ou atualiza existente.
Exemplos:
  SELECT fn_set_markup('supplier', 'uuid-xbz',     120.0, 'XBZ ajuste março');
  SELECT fn_set_markup('category', 'uuid-bolsas',  130.0, 'Bolsas premium');
  SELECT fn_set_markup('product',  'uuid-produto', 140.0, 'Produto especial');

Sincroniza colors de TODOS os produtos a partir de suas variants.
Retorna estatísticas: total, com_cores, sem_cores.
Chamada: SELECT * FROM fn_sync_all_product_colors();

Agrega cores de product_variants para products.colors[].
Usa color_name das variants (que vem de color_variations via color_id).
Chamada: SELECT fn_sync_product_colors_from_variants('uuid-do-produto');
